        rep.check(bool(w.get("path")), f"job {j!r}: the cache step needs a `path`")
        key = str(w.get("key", ""))
        rep.check(f"hashFiles('{c['lock']}')" in key or f'hashFiles("{c["lock"]}")' in key, f"job {j!r}: the cache key must include hashFiles('{c['lock']}') (got {key!r})")

# --- pinned actions
if rules.get("pinned"):
