if rules.get("pinned"):
    for j in jobs:
        for s in steps_of(j):
            u = s.get("uses")
            if u is None or str(u).startswith("./"):
                continue
            ok = re.match(r"^[\w.-]+/[\w.-]+(/[\w./-]+)?@(v\d+(\.\d+){0,2}|[0-9a-f]{40})$", str(u))
            rep.check(ok, f"job {j!r}: `uses: {u}` is not pinned to a version tag or commit SHA")

